import numpy as np
from scipy import stats

# --- helpers ---
df['Loss Date'] = pd.to_datetime(df['Loss Date'], errors='coerce')
df['Valuation Date'] = pd.to_datetime(df['Valuation Date'], errors='coerce')
df['Report Date'] = pd.to_datetime(df['Report Date'], errors='coerce')

# counted rows only (latest valuation per claim+claimant)
counted = df[df['row_kind'] == 'counted'].copy()

metrics = ['Paid to Date', 'Case Reserve', 'Incurred', 'Salvage Subrogation']
seg_cols = ['Line of Business', 'Coverage', 'Claim Status']

# --- EDA (all rows as loaded per domain rules for profiles) ---
try:
    for col in metrics:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# --- SEGMENTATION (counted rows) ---
try:
    for seg in seg_cols:
        for metric in metrics:
            grp = counted.groupby(seg)[metric].sum().nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'sum', 'label': None,
                'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
            })
    # claim count per segment
    for seg in seg_cols:
        grp = counted.groupby(seg)['Claim Number'].nunique().nlargest(10)
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'Claim Number',
            'aggregation': 'count', 'label': 'distinct_claims',
            'results': [{'name': str(k), 'value': float(v)} for k, v in grp.items()]
        })
    # severity (incurred per claim) by Line of Business
    sev = counted.groupby('Line of Business').apply(
        lambda x: x['Incurred'].sum() / x['Claim Number'].nunique()
    ).nlargest(10)
    result['segments'].append({
        'segment_column': 'Line of Business', 'metric_column': 'Incurred',
        'aggregation': 'ratio', 'label': 'severity_incurred_per_claim',
        'results': [{'name': str(k), 'value': float(v)} for k, v in sev.items()]
    })
except Exception:
    pass

# --- CORRELATIONS (counted rows, numeric pairs) ---
try:
    num_cols = [c for c in metrics if counted[c].nunique() > 5]
    corr_mat = counted[num_cols].corr(method='pearson')
    for i, c1 in enumerate(num_cols):
        for c2 in num_cols[i+1:]:
            r = corr_mat.loc[c1, c2]
            if abs(r) >= 0.2:
                result['correlations'][f'{c1}__{c2}'] = round(float(r), 4)
except Exception:
    pass

# --- ANOMALIES (counted rows) ---
try:
    anomaly_list = []
    for col in metrics:
        s = counted[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = max(0, -s.min()) + 1 if s.min() < 0 else 0
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo3, hi3 = q1 - 3*iqr, q3 + 3*iqr
        lo4, hi4 = q1 - 4*iqr, q3 + 4*iqr
        lo5, hi5 = q1 - 5*iqr, q3 + 5*iqr
        mask = (s_t < lo3) | (s_t > hi3)
        frac = mask.sum() / len(s_t)
        if frac > 0.05:
            anomaly_list.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'heavy-tailed; IQR bounds not applied',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed (>{frac*100:.1f}% of values exceed 3×IQR bounds); column excluded from point anomalies'
            })
            continue
        flagged_idx = s_t[mask].index
        if abs(skew) > 2:
            orig_lo = float(np.expm1(lo3) - shift)
            orig_hi = float(np.expm1(hi3) - shift)
        else:
            orig_lo, orig_hi = float(lo3), float(hi3)
        exp_range = f'[{orig_lo:.2f}, {orig_hi:.2f}]'
        for idx in flagged_idx[:25]:
            val = float(counted.loc[idx, col])
            t_val = float(s_t.loc[idx])
            if t_val > hi5 or t_val < lo5:
                sev = 'critical'
            elif t_val > hi4 or t_val < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_list.append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val:.2f} lies outside expected range {exp_range}'
            })
        if len(anomaly_list) >= 25:
            break
    result['anomalies'] = anomaly_list[:25]
except Exception:
    pass

# --- TRENDS (Loss Date MoM on counted rows) ---
try:
    counted['loss_ym'] = counted['Loss Date'].dt.to_period('M')
    for metric in metrics:
        monthly = counted.groupby('loss_ym')[metric].sum().sort_index()
        if len(monthly) < 2:
            continue
        pct = float((monthly.iloc[-1] - monthly.iloc[-2]) / monthly.iloc[-2] * 100) if monthly.iloc[-2] != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': metric, 'period': 'MoM', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
    # YoY by loss year
    counted['loss_yr'] = counted['Loss Date'].dt.year
    for metric in metrics:
        yearly = counted.groupby('loss_yr')[metric].sum().sort_index()
        if len(yearly) < 2:
            continue
        pct = float((yearly.iloc[-1] - yearly.iloc[-2]) / yearly.iloc[-2] * 100) if yearly.iloc[-2] != 0 else 0.0
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        result['trends'].append({
            'column': metric, 'period': 'YoY', 'direction': direction,
            'pct_change': round(pct, 4), 'segment': None
        })
except Exception:
    pass

# --- FORECASTING (simple linear extrapolation on monthly Incurred) ---
try:
    counted['loss_ym'] = counted['Loss Date'].dt.to_period('M')
    monthly_inc = counted.groupby('loss_ym')['Incurred'].sum().sort_index()
    if len(monthly_inc) >= 6:
        x = np.arange(len(monthly_inc))
        y = monthly_inc.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        for step in range(1, 4):
            future_x = len(monthly_inc) - 1 + step
            future_period = str(monthly_inc.index[-1] + step)
            forecast_val = float(intercept + slope * future_x)
            result['forecast_points'].append({'period': future_period, 'value': round(forecast_val, 2)})
except Exception:
    pass

